mapper.select:
SELECT id, partner_user_id, mobile_no, 0 AS newly_created
FROM user_profile
WHERE mobile_no = #{mobileNo}
  AND deleted_at IS NULL
  AND id <> #{userId}
LIMIT 1

mapper.update:
UPDATE user_profile
SET access_token = #{accessToken},
    refresh_token = #{refreshToken},
    access_token_expires_at = #{accessTokenExpiresAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{userId}
  AND deleted_at IS NULL

UPDATE user_profile
SET access_token = #{accessToken},
    access_token_expires_at = #{accessTokenExpiresAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{userId}
  AND deleted_at IS NULL

UPDATE user_profile
SET mobile_no = #{mobileNo}
WHERE id = #{userId}
  AND deleted_at IS NULL

UPDATE user_profile
SET last_login_at = #{lastLoginAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{userId}
  AND deleted_at IS NULL

UPDATE user_profile
SET last_login_device_no = #{deviceNo}
WHERE id = #{userId}
